/* ---------- ENGINE (pure) ---------- */
const fmt=n=>{n=Math.round(n);const a=Math.abs(n);if(a>=1e6)return '$'+(n/1e6).toFixed(a%1e6?2:0).replace(/\.?0+$/,'')+'M';if(a>=1e3)return '$'+Math.round(n/1e3)+'K';return '$'+n};
function taxOn(br,x){let t=0;for(let i=0;i<br.length;i++){const lo=br[i][0],hi=br[i+1]?br[i+1][0]:Infinity;if(x>lo)t+=(Math.min(x,hi)-lo)*br[i][1]}return t}
function taxUSD(j,inc,usFloor){const l=inc/FX[j.cur];let t=taxOn(j.br,l);if(j.mult)t*=j.mult;if(j.br2)t+=taxOn(j.br2,l);if(j.br3)t+=taxOn(j.br3,l);if(j.add)t+=l*j.add;if(j.cap)t=Math.min(t,l*j.cap);t*=FX[j.cur];if(usFloor)t=Math.max(t,taxOn(USF,inc));return t}
const cgUSD=(j,x,us)=>{let t=x*j.cg;if(us)t=Math.max(t,x*.238);return t};
const rad=d=>d*Math.PI/180;
function hav(a,b){const R=6371,dLat=rad(b[0]-a[0]),dLon=rad(b[1]-a[1]);const h=Math.sin(dLat/2)**2+Math.cos(rad(a[0]))*Math.cos(rad(b[0]))*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
const flyH=(a,b)=>{const d=hav(a,b);return d<50?0:Math.round((d/830+1.1)*10)/10};
const incFrom=v=>Math.round(150000*Math.pow(10000000/150000,v/100)/5000)*5000;
const exitFrom=v=>v==0?0:Math.round(Math.pow(v/100,2)*100e6/1e5)*1e5;
function computeRows(S){
  const us=S.pp.has('us');const home=HOMES[S.home];
  const rows=J.map(j=>{
    const tax=taxUSD(j,S.inc,us),net=S.inc-tax,kept10=net*10+S.exit-cgUSD(j,S.exit,us),eff=tax/S.inc;
    let fr=j.visa._;for(const p of S.pp){if(j.visa[p]!=null&&j.visa[p]<fr)fr=j.visa[p]}
    const fly=flyH([home[1],home[2]],[j.lat,j.lon]);
    return{j,tax,eff,net,kept10,fr,fly}});
  const mx=Math.max(...rows.map(r=>r.kept10)),mn=Math.min(...rows.map(r=>r.kept10));
  const w={...S.w};w.school*=S.hh==='kids'?1:S.hh==='couple'?.3:0;const tw=Object.values(w).reduce((a,b)=>a+b,0)||1;
  rows.forEach(r=>{const j=r.j;const n={tax:(r.kept10-mn)/((mx-mn)||1),safe:j.safe/10,school:j.school/10,sun:Math.min(1,Math.max(0,(j.sun-1500)/2000)),prox:1-Math.min(1,r.fly/18),beauty:j.beauty/10,cost:1-(j.cost-60)/70,visa:1-(r.fr-1)/3};
    r.score=Object.keys(w).reduce((a,k)=>a+w[k]*n[k],0)/tw;r.tags=[];
    if(r.eff<.005)r.tags.push('0% income tax');else if(r.eff<.18)r.tags.push('Low effective tax');
    if(j.regime)r.tags.push({t:j.regime.length>48?j.regime.slice(0,46)+'…':j.regime,w:1});if(j.wealth)r.tags.push({t:'Wealth tax',w:1});
    if(us&&j.cur!=='USD')r.tags.push({t:'US tax floor applied',w:1});
    if(r.fr===1)r.tags.push('Walk in');else if(r.fr>=4)r.tags.push({t:'Quota permit',w:1});
    if(r.fly>0&&r.fly<=5)r.tags.push('Under 5h from home');const fl=FLOW[j.cc];if(fl>=3000)r.tags.push('Top 4 wealth magnet 2025');else if(fl<=-3000)r.tags.push({t:'Net wealth exodus 2025',w:1});});
  rows.sort((a,b)=>b.score-a.score);return rows}
